import{_ as s,C as i,c as r,o as n,a3 as o,G as t}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Public holidays","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/setup/public-holidays.md","filePath":"master/human-resources/time-off/setup/public-holidays.md","lastUpdated":1793074831000}'),l={name:"master/human-resources/time-off/setup/public-holidays.md"};function d(h,e,c,u,g,p){const a=i("ImagePopup");return n(),r("div",null,[e[0]||(e[0]=o('<h1 id="public-holidays" tabindex="-1">Public holidays <a class="header-anchor" href="#public-holidays" aria-label="Permalink to &quot;Public holidays&quot;">​</a></h1><p>A public holiday is a date or a short range of dates when the whole company is off, such as New Year&#39;s Day. You keep them in one list so everyone can look them up. Staff see the list in the <strong>Holidays</strong> window on <strong>My Time</strong>.</p><blockquote><p><strong>In simple words:</strong> Public holidays are the shared days off of your company, kept in one list.</p></blockquote><p>Open <code>Time Off → Configuration → Public Holidays</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The <strong>Calendar</strong> field uses a working schedule. A working schedule lists the days and hours a team works. Pick one that already exists, such as <strong>Flexible 40 hours/week</strong>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page lists each holiday. The columns are <strong>Name</strong>, <strong>Start Date</strong>, <strong>End Date</strong> and <strong>Calendar</strong>. Use the search box to find a name, for example <code>Day</code>. Group the list by <strong>Start Date</strong>, <strong>End Date</strong> or <strong>Company Name</strong>. Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>.</p><p>Sample data includes holidays of 2025, from <strong>New Year&#39;s Day</strong> to <strong>Christmas Day</strong>. They use the calendar <strong>Flexible 40 hours/week</strong>. Dates show as <code>2025-01-01</code>. Use the page numbers below the table to see more rows.</p>',8)),t(a,{src:"/images1/time-off/to_set_holidays_list.png",alt:"Public Holidays list showing New Year's Day, Republic Day and Gandhi Jayanti with start and end dates and the calendar"}),e[1]||(e[1]=o('<h2 id="create-a-public-holiday" tabindex="-1">Create a public holiday <a class="header-anchor" href="#create-a-public-holiday" aria-label="Permalink to &quot;Create a public holiday&quot;">​</a></h2><p>This example adds <strong>Company Foundation Day</strong>.</p><ol><li>Open <code>Time Off → Configuration → Public Holidays</code>.</li><li>Click <strong>New Public Holiday</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Company Foundation Day</code>.</li><li><strong><em>Start Date:</em></strong> Required. Pick the first day. Dates show like <code>Oct 20, 2026</code>.</li><li><strong><em>End Date:</em></strong> Required. Pick the last day. For one day, pick the same date.</li><li><strong><em>Calendar:</em></strong> Optional. Choose <strong>Flexible 40 hours/week</strong>.</li></ul>',4)),t(a,{src:"/images1/time-off/to_set_holiday_form.png",alt:"Create Public Holidays window with Company Foundation Day, one day range and calendar Flexible 40 hours/week"}),e[2]||(e[2]=o('<ol start="4"><li>Click <strong>Create</strong>. The window closes and the holiday joins the list.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create &amp; create another</strong> to add several holidays in a row.</p></div><h2 id="where-holidays-show" tabindex="-1">Where holidays show <a class="header-anchor" href="#where-holidays-show" aria-label="Permalink to &quot;Where holidays show&quot;">​</a></h2><p>Open <code>Time Off → My Time → Dashboard</code>. Click the round blue icon button next to <strong>New Time Off</strong>. A <strong>Holidays</strong> panel slides in from the right with two sections: <strong>Public Holidays</strong> and <strong>Mandatory Holidays</strong>. Each public holiday shows its name and its date or date range. Scroll down to see <strong>Mandatory Holidays</strong>.</p>',4)),t(a,{src:"/images1/time-off/to_set_holidays_window.png",alt:"Holidays window on My Time with the Public Holidays section listing names and dates"}),e[3]||(e[3]=o('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>A public holiday does not change the <strong>Duration</strong> of a request. <strong>Duration</strong> skips Saturdays and Sundays only.</p></div><h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> to change the name, dates or calendar, then <strong>Save changes</strong>. Click <strong>Delete</strong> to remove a holiday. Click <strong>View</strong> for a read-only window.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./mandatory-days.html">Mandatory days</a></li><li><a href="./time-off-types.html">Leave types</a></li><li><a href="./../requests/my-time.html">My Time</a></li></ul>',5))])}const f=s(l,[["render",d]]);export{y as __pageData,f as default};
